package cn.naiblog.carsearch.wechat;
import cn.naiblog.carsearch.config.SettingService;import org.junit.jupiter.api.Test;import tools.jackson.databind.ObjectMapper;import java.util.Map;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;
class WechatMessageCryptoServiceTest{@Test void encryptedResponseCanBeVerifiedAndDecrypted()throws Exception{SettingService settings=mock(SettingService.class);when(settings.secure("wechat_message_token","")).thenReturn("Token123");when(settings.secure("wechat_message_aes_key","")).thenReturn("abcdefghijklmnopqrstuvwxyz0123456789ABCDEFG");when(settings.wechat()).thenReturn(new SettingService.WechatConfig("wx-test-app","secret","offer","sandbox","production",0));ObjectMapper mapper=new ObjectMapper();WechatMessageCryptoService crypto=new WechatMessageCryptoService(settings,mapper);Map<String,Object>envelope=crypto.response(Map.of("ErrCode",0,"ErrMsg","ok"));String body=mapper.writeValueAsString(Map.of("Encrypt",envelope.get("Encrypt")));Map<String,Object>plain=crypto.envelope(body,String.valueOf(envelope.get("MsgSignature")),String.valueOf(envelope.get("TimeStamp")),String.valueOf(envelope.get("Nonce")));assertThat(plain).containsEntry("ErrCode",0).containsEntry("ErrMsg","ok");}}
